// Actions/private D-Bus HTTP boundary. No target UID is echoed in result/errors.
fn buddy_check_http_config(root:&str)->serde_json::Value{let mut c=org_relation_http_config(root);c["profile"]["org_relation_sync"]=serde_json::Value::Null;c["profile"]["buddy_relation_check"]=serde_json::json!({"check":true});c}
fn buddy_check_http_body()->serde_json::Value{serde_json::json!({"expected_revision":1,"target_uid":"1_2","consent":true})}
#[tokio::test]async fn buddy_check_http_current_original_peer_returns_only_two_fields_then_stops_and_joins(){Box::pin(async{
 use crate::connectivity::app_voice::providers::jegotrip as n;let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let listener=tokio::net::TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&tokio_rustls::rustls::version::TLS13);let mut cfg=buddy_check_http_config(&cert.root);cfg["profile"]["route"]["router_common"]["reference"]=serde_json::json!(format!("Router:tls -h 127.0.0.1 -p {port} -ri 12001;"));cfg["profile"]["route"]["router_common"]["anchors"][0]["port"]=serde_json::json!(port);
 let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":cfg})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);let(tx,rx)=tokio::sync::oneshot::channel();let peer=tokio::spawn(Box::pin(n::relation_http_test_peer::serve_buddy_check(listener,server,rx)));
 let(status,_,_)=account_request(&served,reqwest::Method::POST,&format!("/api/non-3gpp/accounts/{line}/start"),Some(serde_json::json!({"expected_revision":1})),Some(&cookie)).await;assert_eq!(status,StatusCode::ACCEPTED);tokio::time::timeout(std::time::Duration::from_secs(6),async{while state.app.app_accounts.get(&line,100).await.unwrap().phase!="hosted"{tokio::task::yield_now().await;}}).await.unwrap();
 let(status,headers,body)=account_request(&served,reqwest::Method::POST,&format!("/api/non-3gpp/accounts/{line}/buddy-relation/check"),Some(buddy_check_http_body()),Some(&cookie)).await;assert_eq!(status,StatusCode::OK);no_store(&headers);no_secrets(&body);assert_eq!(serde_json::from_str::<serde_json::Value>(&body).unwrap()["data"],serde_json::json!({"accepted":true,"relation_type":4294967295u32}));for private in ["1_2","fixture-user","fixture-auth","secret","not-a-grant"]{assert!(!body.contains(private));}assert!(state.app.app_accounts.relation_write_history(&line,128).unwrap().is_empty());assert!(state.app.database.get_recent_app_events(Some(&line),128).unwrap().is_empty());tx.send(()).unwrap();let(status,headers,body)=account_request(&served,reqwest::Method::POST,&format!("/api/non-3gpp/accounts/{line}/stop"),Some(serde_json::json!({"expected_revision":1})),Some(&cookie)).await;assert_eq!(status,StatusCode::OK);no_store(&headers);no_secrets(&body);peer.await.unwrap();assert!(!state.app.app_accounts.get(&line,100).await.unwrap().io_cleanup_required);
}).await;}
#[tokio::test]async fn buddy_check_http_requires_auth_and_rejects_foreign_fields_without_business_or_echo(){let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let path="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/buddy-relation/check";let(status,_,body)=account_request(&served,reqwest::Method::POST,path,Some(buddy_check_http_body()),None).await;assert_eq!(status,StatusCode::UNAUTHORIZED);no_secrets(&body);let cookie=authenticate(&served).await;for field in ["token","uid","scope","nonce","relation_type","clear_unknown","write_consent"]{let mut input=buddy_check_http_body();input[field]=serde_json::json!("private-forgery");let(status,headers,body)=account_request(&served,reqwest::Method::POST,path,Some(input),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);assert!(!body.contains("private-forgery"));}assert!(state.app.app_accounts.list(100).await.unwrap().is_empty());}
#[tokio::test]async fn buddy_check_http_rejects_non_uid_targets_and_requires_explicit_consent(){let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let path="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/buddy-relation/check";for target in ["","+12345","1-2","P2P/1_2","[uid:1_2]","1_0","1_2\n"]{let mut input=buddy_check_http_body();input["target_uid"]=serde_json::json!(target);let(status,headers,body)=account_request(&served,reqwest::Method::POST,path,Some(input),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}let mut input=buddy_check_http_body();input["consent"]=serde_json::json!(false);let(status,headers,body)=account_request(&served,reqwest::Method::POST,path,Some(input),Some(&cookie)).await;assert_eq!(status,StatusCode::FORBIDDEN);no_store(&headers);no_secrets(&body);}
#[tokio::test]async fn buddy_check_http_default_off_policy_does_not_require_or_enable_directory_or_write(){let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let good=buddy_check_http_config(&cert.root);for mode in 0..4{let mut c=good.clone();match mode{0=>c["profile"]["buddy_relation_check"]=serde_json::json!({"check":false}),1=>c["profile"]["buddy_relation_check"]=serde_json::json!({"check":true,"write":true}),2=>c["profile"]["client_ex"]=serde_json::json!(false),_=>c["profile"]["native_receivers"]=serde_json::Value::Null}let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":c})),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_secrets(&body);}let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":good})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);let path=format!("/api/non-3gpp/accounts/{line}/buddy-relation/check");let(status,headers,body)=account_request(&served,reqwest::Method::POST,&path,Some(buddy_check_http_body()),Some(&cookie)).await;assert_eq!(status,StatusCode::SERVICE_UNAVAILABLE);no_store(&headers);no_secrets(&body);assert_eq!(state.app.app_accounts.get(&line,100).await.unwrap().phase,"stopped");assert!(state.app.app_accounts.relation_write_history(&line,128).unwrap().is_empty());}
